                // Usamos una expresión regular para asegurar que reemplazamos la coordenada completa, 
                // incluyendo posibles caracteres de formato.
                const regex = new RegExp(`\\b${coord}\\b`, 'g');
                expression = expression.replace(regex, value);
            } else {
                // Si el valor no es numérico, lo trataremos como un string y fallará la evaluación, 
                // o simplemente omitiremos su sustitución numérica para evitar errores de eval().
            }
        }

        // Evaluar la expresión matemática resultante (ej: "2-3")
        const result = new Function(`return ${expression}`)();
        return Math.round(result * 100) / 100;

    } catch (e) {
        console.warn("Error al evaluar fórmula:", e);
        // Si falla, devolvemos la fórmula original para que el usuario vea qué falló.
        return formula; 
    }
}
