### FUNCION: calculateValue
```javascript
/**
 * Intenta evaluar una fórmula matemática o de función (como SUMA) basada en el estado actual.
 * @param {string} formulaStr - La cadena que empieza con '='.
 * @param {Object} state - El objeto global 'estado' con todos los valores de las celdas.
 * @returns {string|number} El resultado calculado o la fórmula original si falla.
 */
function calculateValue(formulaStr, state) {
    let formula = formulaStr;

    // 1. Preprocesar referencias de celda (A1, B2...) a sus valores reales.
    // Esto reemplaza coordenadas con su valor numérico o '0' si no existen.
    let processedFormula = formula.replace(/[A-Z]+[0-9]+/g, (match) => {
        const coord = match;
        const value = state[coord];
        return (value !== undefined && value !== "") ? String(parseFloat(value)) : "0";
    });

    // 2. Manejar funciones específicas como SUMA() o rangos de celdas.
    let finalExpression = processedFormula;

    // Detectar y procesar SUMA(rango) o SUMA(c1; c2)
    const sumMatch = finalExpression.match(/SUMA\(([^)]+)\)/i);
    if (sumMatch) {
        let content = sumMatch[1];

        // Separamos por rangos (:), comas (,), o punto y coma (;)
        const parts = content.split(/[:;,]/).filter(p => p.trim() !== "");
        let sumTotal = 0;

        parts.forEach(part => {
            if (part.includes(':')) {
                // Rango: A1:A3 -> Sumar individualmente
                const [startCoord, endCoord] = part.split(':').map(c => c.trim());
                let currentRangeSum = 0;

                // Lógica muy simplificada para iterar en un rango de la misma columna (ej: A1 a A3)
                if (startCoord && endCoord) {
                    const startCol = startCoord[0];
                    const startIndex = parseInt(startCoord.substring(1));
                    const endIndex = parseInt(endCoord.substring(1));

                    for (let r = startIndex; r <= endIndex; r++) {
                        const coord = `${startCol}${r}`;
                        const value = state[coord];
                        if (value !== undefined && value !== "") {
                            currentRangeSum += parseFloat(value);
                        }
                    }
                } else {
                    // Si no podemos parsear el rango, asumimos 0 o lo ignoramos.
                }
                sumTotal += currentRangeSum;

            } else if (part) {
                // Celda suelta: A1
                const coord = part.trim();
                if (state[coord] !== undefined && state[coord] !== "") {
                    sumTotal += parseFloat(state[coord]);
                }
            }
        });
        return String(sumTotal); // Devolvemos el resultado numérico como string
    }

    // 3. Evaluación matemática general (resta, multiplicación, división)
    try {
        // Evaluar la expresión restante usando eval() para operaciones básicas de JS.
        const result = eval(finalExpression);
        return String(result);
    } catch (e) {
        console.warn("Error al evaluar la fórmula:", e);
        return formula; // Si falla, devolvemos la fórmula original
    }
}
