/**
 * Calcula el valor efectivo de una celda, resolviendo fórmulas si es necesario.
 * Esto maneja la recursión para calcular dependencias (ej: A1 necesita B1).
 * @param {string} coord - Coordenada de la celda (ej: "A1").
 * @returns {any} El valor calculado o el texto literal.
 */
function getEffectiveValue(coord) {
    let rawInput = estado[coord];
    if (!rawInput || typeof rawInput !== 'string') return "";

    const trimmedInput = rawInput.trim();

    // Si no es fórmula, devolvemos directamente lo almacenado (texto literal).
    if (!trimmedInput.startsWith('=')) {
        return rawInput;
    }

    let formulaBody = trimmedInput.substring(1);

    // Regex para encontrar patrones de coordenadas de celda (Ej: A1, B20)
    const matches = formulaBody.match(/[A-Z]+\d+/g); 
    if (!matches) {
        return rawInput; // Fórmula sin referencias detectables.
    }

    let substitutedFormula = formulaBody;

    // Ordenar por longitud descendente para asegurar que AA1 no se trate como A1 + extra
    matches.sort((a, b) => b.length - a.length); 

    for (const match of matches) {
        try {
            // Obtener el valor efectivo de la dependencia llamando recursivamente
            const dependencyValue = getEffectiveValue(match); 

            // Reemplazar la referencia con su valor calculado, escapándolo para eval()
            // Usamos JSON.stringify para asegurar que números y cadenas se manejen correctamente en una expresión matemática.
            substitutedFormula = substitutedFormula.replace(new RegExp(match, 'g'), JSON.stringify(dependencyValue)); 
        } catch (e) {
             console.error(`Error al resolver dependencia ${match} para ${coord}.`, e);
             // Si falla la dependencia, simplemente continuamos con el resto de la fórmula sin actualizar ese término.
        }
    }

    try {
        // Evaluar la expresión matemática resultante.
        // Nota: Se usa eval() por simplicidad en un entorno limitado y para resolver referencias de variables (celdas).
        const result = eval(substitutedFormula);
        return isNaN(result) ? rawInput : result; // Si el resultado es NaN, devolvemos la fórmula original.
    } catch (e) {
        console.error(`Error evaluando fórmula en ${coord}:`, e);
        return rawInput; // Devolver la fórmula si falla la evaluación.
    }
}
