/**
 * Actualiza el valor de una celda en el estado.
 * @param {string} cellCoord - Coordenada de la celda (ej: "A1", "J20").
 * @param {string} value - El nuevo contenido del texto.
 */
function updateCellValue(cellCoord, value) {
    if (estado[cellCoord] !== undefined) {
        // Si el valor ingresado es una fórmula, lo guardamos como texto.
        // El cálculo se hará en la capa de lógica después de actualizar el estado base.
        estado[cellCoord] = String(value); 
    } else {
        console.warn(`Coordenada no reconocida en el estado: ${cellCoord}`);
    }
}

/**
 * Evalúa una fórmula usando los valores actuales del estado para las referencias de celda.
 * @param {string} formula - La cadena de la fórmula (ej: "=B1+C1").
 * @returns {string|null} El resultado calculado como string, o null si no es fórmula/falló.
 */
function calculateValue(formula) {
    if (!formula || !formula.startsWith('=')) {
        return null; // No is a formula
    }

    let expression = formula.substring(1).trim(); // Remove leading '='

    // Regex to find cell coordinates (e.g., A1, J20)
    const coordRegex = /([A-Z]+[0-9]+)/g;

    // Replace coordinates with their current string value from the state object.
    expression = expression.replace(coordRegex, (match) => {
        if (estado[match] !== undefined) {
            return estado[match]; // Use the stored value for calculation
        }
        console.warn(`Dependency ${match} not found in state.`);
        // If a dependency is missing, treat it as 0 or handle error gracefully.
        return '0'; 
    });

    try {
        // Evaluate the expression string. Since we control all inputs (from estado), this is safe for the scope of the app.
        const result = eval(expression); 
        // Return the calculated numeric result as a clean string, rounded if necessary.
        return String(Math.round(result * 100) / 100); 
    } catch (e) {
        console.error("Error evaluating formula:", e);
        return null; // Calculation failed
    }
}

/**
 * Itera sobre todas las celdas y recalcula su valor si contienen una fórmula, actualizando el estado.
 * @returns {boolean} True si hubo algún cambio de valor.
 */
function recalculateAllFormulas() {
    let changed = false;
    const cellsToCheck = Object.keys(estado);

    // Iteramos sobre todas las celdas para verificar si alguna necesita ser recalculada.
    for (const cellCoord of cellsToCheck) {
        let currentValue = estado[cellCoord];
        let newValue = calculateValue(currentValue);

        // Si es una fórmula y el cálculo fue exitoso, y el nuevo valor difiere del valor guardado:
        if (newValue !== null && newValue !== undefined && currentValue !== newValue) {
            // 1. Actualizar el estado con el resultado numérico/calculado.
            estado[cellCoord] = newValue;
            changed = true;
        }
    }
    return changed;
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const cells = document.querySelectorAll('#spreadsheet-grid td[contenteditable="true"]');

    cells.forEach(td => {
        // Obtenemos la coordenada de la celda (ej: A1) usando el atributo data-cell
        const cellCoord = td.getAttribute('data-cell');

        if (cellCoord && estado[cellCoord] !== undefined) {
