### FUNCION: showColorMenu
```javascript
function showColorMenu(event, target) {
    // Prevenir el menú contextual por defecto del navegador
    event.preventDefault();

    const cellCoord = target.getAttribute('data-cell');
    if (!cellCoord) return;

    let menu = document.getElementById('color-menu');
    let container = document.querySelector('#spreadsheet-container');

    // 1. Crear o reutilizar el menú de color en el contenedor principal
    if (!menu) {
        menu = document.createElement('div');
        menu.id = 'color-menu';
        menu.style.cssText = `
            position: absolute; z-index: 20; background: white; border: 1px solid #ccc; padding: 5px; box-shadow: 0 4px 8px rgba(0,0,0,0.1); display: none;
        `;
        container.appendChild(menu);
    }

    // Limpiar contenido previo
    menu.innerHTML = '';

    const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FFA500']; // Rojo, Verde, Azul, Amarillo, Naranja

    // 2. Generar botones de color
    colors.forEach(color => {
        const button = document.createElement('button');
        button.className = 'color-picker-btn';
        button.style.backgroundColor = color;
        button.style.width = '30px';
        button.style.height = '30px';
        button.style.border = '1px solid #ccc';
        button.style.margin = '2px';
        button.style.cursor = 'pointer';
        button.onclick = () => applyColor(color, target);
        menu.appendChild(button);
    });

    // 3. Posicionar el menú cerca del evento
    const rect = target.getBoundingClientRect();
    menu.style.left = `${rect.left}px`;
    menu.style.top = `${rect.bottom + window.scrollY - menu.offsetHeight - 10}px`;
    menu.style.display = 'block';

    // 4. Añadir un listener para cerrar el menú al hacer clic fuera
    document.addEventListener('click', handleMenuClickOutside);
}

function handleMenuClickOutside(event) {
    const menu = document.getElementById('color-menu');
    if (menu && !menu.contains(event.target) && event.target.closest('[contenteditable="true"]') !== event.target.closest('.color-picker-btn')) {
        menu.style.display = 'none';
        document.removeEventListener('click', handleMenuClickOutside);
    }
}

function applyColor(color, target) {
    const cellCoord = target.getAttribute('data-cell');
    if (cellCoord) {
        // 1. Actualizar el estado con el nuevo color y preservar el valor actual
        estado[cellCoord].backgroundColor = color;
        guardar(); // Guardamos inmediatamente el cambio de estilo/datos
        render(); // Volvemos a dibujar para aplicar el fondo visualmente
    }
    // Ocultar menú después de la acción
    document.getElementById('color-menu').style.display = 'none';
    document.removeEventListener('click', handleMenuClickOutside);
}
