### FUNCION: selectColumn
```javascript
function selectColumn(columnLetter) {
    // 1. Limpiar selección previa y controles de UI
    selectedColumn = columnLetter;
    const controls = document.getElementById('column-controls');
    if (controls) {
        controls.style.display = 'block';
    }

    // Desactivar resaltado anterior en todos los encabezados
    document.querySelectorAll('.col-header').forEach(th => {
        th.classList.remove('selected-column');
    });

    // 2. Aplicar resaltado al encabezado actual
    const currentHeader = document.querySelector(`.col-header[data-column="${columnLetter}"]`);
    if (currentHeader) {
        currentHeader.classList.add('selected-column');
    }

    // Opcional: Actualizar el estado para reflejar la selección, aunque no es estrictamente necesario si solo se usa localmente.
    console.log(`Columna seleccionada: ${columnLetter}`);
}
```

### FUNCION: deleteColumn
```javascript
function deleteColumn() {
    if (!selectedColumn) return;

    const column = selectedColumn;
    if (!confirm(`¿Está seguro de que desea eliminar la columna ${column}? Esto borrará todos los datos y la estructura.`)) {
        return;
    }

    // 1. Eliminar el contenido del estado para todas las celdas de esa columna (A1, A2, etc.)
    for (let r = 1; r <= 20; r++) {
        const cellCoord = `${column}${r}`;
        delete estado[cellCoord];
    }

    // 2. Eliminar la estructura DOM y el encabezado de columna
    const columnHeader = document.querySelector(`.col-header[data-column="${column}"]`);
    if (columnHeader) {
        columnHeader.parentNode.removeChild(columnHeader);
    }

    // Eliminar todas las celdas de datos en la columna (esto es más complejo ya que afecta a 20 filas)
    const tbody = document.querySelector('#spreadsheet-grid tbody');
    if (tbody) {
        for (let r = 1; r <= 20; r++) {
            // Selecciona el TD específico en la fila 'r' y columna 'column'
            const row = tbody.children[r - 1]; // Fila 1 es índice 0, Fila 20 es índice 19
            if (row) {
                const tdToRemove = row.querySelector(`[data-cell="${column}${r}"]`);
                if (tdToRemove) {
                    tdToRemove.remove();
                }
            }
        }
    }

    // 3. Limpiar la selección y redibujar/guardar
    selectedColumn = null;
    document.getElementById('column-controls').style.display = 'none';
    render();
    guardar();
}
```

