### FUNCION: colorColumnBackground
```javascript
function colorColumnBackground() {
    if (!selectedColumn) return;

    const column = selectedColumn;
    const newColor = prompt("Ingrese el color de fondo deseado (ej: #ffddaa o red):", "#ffffcc");
    if (!newColor) return; // El usuario canceló

    // 1. Aplicar estilo a todas las celdas en la columna seleccionada
    let updatedDOMCells = 0;
    const tbody = document.querySelector('#spreadsheet-grid tbody');
    if (tbody) {
        for (let r = 1; r <= 20; r++) {
            // Selecciona el TD específico en la fila 'r' y columna 'column'
            const row = tbody.children[r - 1];
            if (row) {
                const td = row.querySelector(`[data-cell="${column}${r}"]`);
                if (td) {
                    td.style.backgroundColor = newColor;
                    updatedDOMCells++;
                }
            }
        }
    }

    // Nota: No se modifica el estado, solo la representación visual (DOM).
    console.log(`Fondo de columna ${column} cambiado a ${newColor}. Total celdas afectadas: ${updatedDOMCells}`);
}
