### FUNCION: conectar
```js
function conectar() {
    const tbody = document.querySelector('#spreadsheet-grid tbody');
    if (!tbody) return;

    // --- 1. Listener para edición de celdas (EXISTENTE) ---
    tbody.addEventListener('blur', (event) => {
        const target = event.target;

        // Verificamos si el elemento objetivo es una celda de datos editable
        if (target && target.hasAttribute('contenteditable') && target.dataset.cell) {
            const cellCoord = target.getAttribute('data-cell');
            let newValue = target.textContent; 

            // 1. LÓGICA: Actualizar el estado con el nuevo valor del DOM
            updateCellValue(cellCoord, newValue);
        }
    }, true); // Usamos la fase de captura para interceptar eventos antes que se propaguen

    // --- 2. Listener para selección y acciones de columnas (NUEVO) ---

    // Event listeners para los encabezados de columna (.col-header)
    document.querySelectorAll('.col-header').forEach(header => {
        header.addEventListener('click', (e) => {
            const column = e.currentTarget.dataset.column;
            selectColumn(column);
        });
    });

    // Event listeners para los controles de columna (NUEVO)
    document.getElementById('delete-column-btn')?.addEventListener('click', deleteColumn);
    document.getElementById('clear-content-btn')?.addEventListener('click', clearColumnContent);
    document.getElementById('color-background-btn')?.addEventListener('click', colorColumnBackground);
}
```

