### FUNCION: initializeEstado
```js
function initializeEstado() {
    const state = {};
    // Columnas A-J (índice 0 a 9)
    const columns = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
    // Filas 1-20
    for (let r = 1; r <= 20; r++) {
        for (let c = 0; c < columns.length; c++) {
            const col = columns[c];
            const cellCoord = `${col}${r}`;
            state[cellCoord] = ""; // Inicialmente vacío
        }
    }
    return state;
}
```

### FUNCION: handleSelectColumn
```js
function handleSelectColumn(event) {
    const button = event.target.closest('.col-control-btn');
    if (!button) return;

    const col = button.dataset.column;
    let selectedCoord = null;

    // Desactivar todos los botones y limpiar la selección visual
    document.querySelectorAll('.col-control-btn').forEach(btn => {
        btn.style.backgroundColor = '#e0e0e0';
        btn.setAttribute('aria-pressed', 'false');
    });

    // Activar el botón seleccionado
    button.style.backgroundColor = '#cceeff'; // Color de selección visual
    button.setAttribute('aria-pressed', 'true');
    selectedCoord = col;

    // Actualizar estado de los controles (habilitar/deshabilitar botones de acción)
    const actionsDisabled = !col; 
    document.getElementById('delete-column-btn').disabled = actionsDisabled;
    document.getElementById('clear-column-btn').disabled = actionsDisabled;
    document.getElementById('color-column-btn').disabled = actionsDisabled;

    // Al seleccionar una columna, forzamos un redibujado para reflejar el estado de los controles (aunque esto solo cambia la UI)
    render(); 
}
```

