### FUNCION: deleteColumn
```js
function deleteColumn(selectedCol) {
    if (!selectedCol) return;

    if (!confirm(`¿Está seguro de que desea borrar la columna ${selectedCol}? Esta acción es irreversible.`)) {
        return;
    }

    // 1. Limpiar el estado para esta columna
    for (let r = 1; r <= 20; r++) {
        const cellCoord = `${selectedCol}${r}`;
        delete estado[cellCoord];
    }

    // 2. Eliminar los elementos del DOM (Header y Celdas de datos)

    // En el thead: eliminar la columna header 'th'
    const colHeaderToRemove = document.querySelector(`.col-header[data-column="${selectedCol}"]`);
    if (colHeaderToRemove) {
        colHeaderToRemove.remove();
    }

    // En el tbody: encontrar y eliminar todas las celdas 'td' con esta clase/atributo de columna
    const cellsToDelete = document.querySelectorAll(`td[data-cell^="${selectedCol}"]`);
    cellsToDelete.forEach(cell => cell.remove());

    // 3. Guardar y Redibujar
    guardar();
    render(); // Renderiza para asegurar que el estado se refleje visualmente (aunque ya eliminamos los elementos)
}
