### FUNCION: conectar
```js
function conectar() {
    const tbody = document.querySelector('#spreadsheet-grid tbody');
    if (!tbody) return;

    // 1. Event delegation para la edición de celdas (Blur/Input)
    tbody.addEventListener('blur', (event) => {
        const target = event.target;

        if (target && target.hasAttribute('contenteditable') && target.dataset.cell) {
            const cellCoord = target.getAttribute('data-cell');
            let newValue = target.textContent; 

            updateCellValue(cellCoord, newValue);
            guardar();
            render();
        }
    }, true); 

    // 2. Event Listener para la selección de columna (Header Click)
    const colHeaders = document.querySelectorAll('.col-header');
    colHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const columnLetter = this.getAttribute('data-column');
            handleSelectColumn(columnLetter);
        });
    });

    // 3. Event Listeners para los Controles de Columna (Buttons/Select)
    document.getElementById('column-selector').addEventListener('change', function() {
        const columnLetter = this.value;
        if (columnLetter) {
            handleSelectColumn(columnLetter);
        }
    });

    document.getElementById('btn-clear-column').addEventListener('click', () => {
        const selectedCol = document.getElementById('column-selector').value;
        if (selectedCol) {
            clearColumnContent(selectedCol);
        }
    });

    document.getElementById('btn-color-column').addEventListener('click', () => {
        const selectedCol = document.getElementById('column-selector').value;
        if (selectedCol) {
            changeColumnBackgroundColor(selectedCol);
        }
    });

    document.getElementById('btn-delete-column').addEventListener('click', () => {
        if (!confirm("¿Está seguro de que desea eliminar esta columna? Esta acción es irreversible.")) return;
        const selectedCol = document.getElementById('column-selector').value;
        if (selectedCol) {
            // Aquí se debería manejar la eliminación visual del DOM también, pero por ahora solo limpiamos el estado.
            deleteColumn(selectedCol);
        }
    });
}
