### FUNCION: borrarColumna
```js
/**
 * Elimina completamente una columna (header y todas las celdas de datos).
 */
function borrarColumna() {
    if (!estado.selectedColumn) {
        alert("Por favor, seleccione una columna primero.");
        return;
    }

    const columnLetter = estado.selectedColumn;
    const columnHeader = document.querySelector(`.col-header[data-column="${columnLetter}"]`);

    if (!columnHeader) return;

    // 1. Recorrer todas las filas del cuerpo y eliminar el TD correspondiente
    document.querySelectorAll(`td[data-cell^="${columnLetter}"]:not([data-row=""])`).forEach(td => {
        const cellCoord = td.getAttribute('data-cell');
        // Limpiar contenido en el estado antes de borrar la celda del DOM
        updateCellValue(cellCoord, ""); 
        // El TD será eliminado con la columna header, pero es bueno asegurarse.
    });

    // 2. Eliminar el encabezado de la columna (la letra)
    columnHeader.remove();

    // 3. Recorrer todas las filas y eliminar el elemento TD que corresponde a esta columna
    const allRows = document.querySelectorAll('#spreadsheet-grid tbody tr');
    allRows.forEach(row => {
        // Busca la celda dentro de esa fila con el data-cell match
        const cellToRemove = row.querySelector(`td[data-cell^="${columnLetter}"]`);
        if (cellToRemove) {
            cellToRemove.remove();
        }
    });

    // 4. Limpiar estado y UI
    deseleccionarColumna();
    estado.selectedColumn = null;
    console.log(`Columna ${columnLetter} eliminada exitosamente.`);
}
