function deleteColumn(colLetter) {
    if (!estado.selectedColumn || estado.selectedColumn !== colLetter) return;

    const columnIndex = Array.from(document.querySelectorAll('.col-header')).findIndex(th => th.dataset.column === colLetter);
    if (columnIndex === -1) return;

    // 1. Eliminar el encabezado de la columna
    const headerToDestroy = document.querySelector(`.col-header[data-column="${colLetter}"]`);
    if (headerToDestroy) {
        headerToDestroy.remove();
    } else {
        console.error("Header no encontrado para eliminar.");
        return;
    }

    // 2. Eliminar el contenido de la columna del estado y del DOM
    const cellsToDelete = document.querySelectorAll(`[data-cell^="${colLetter}"]`);
    cellsToDelete.forEach(td => {
        const cellCoord = td.getAttribute('data-cell');
        delete estado[cellCoord]; // Limpiar el estado
        td.remove(); // Eliminar del DOM
    });

    // 3. Actualizar la selección y redibujar
    estado.selectedColumn = null;
    document.getElementById('current-column-display').textContent = 'Columna seleccionada';
    const controlsPanel = document.getElementById('column-controls');
    controlsPanel.classList.remove('active');

    render(); // Renderizar para asegurar que el estado es correcto y limpiar cualquier caché visual
    guardar();
}
