```js
function conectar() {
    // 1. Event delegation para la selección de columna (clic en letras A-J)
    const headerRow = document.querySelector('.col-header-row');
    if (headerRow) {
        headerRow.addEventListener('click', handleColumnSelectionClick);
    }

    // 2. Event delegation para el manejo de edición de celdas (guardar valor al perder foco)
    const tbody = document.querySelector('#spreadsheet-grid tbody');
    if (!tbody) return;

    // Escuchamos 'blur' en las celdas de datos editable.
    tbody.addEventListener('blur', (event) => {
        const target = event.target;

        // Verificamos si el elemento objetivo es una celda de datos editable
        if (target && target.hasAttribute('contenteditable') && target.dataset.cell) {
            const cellCoord = target.getAttribute('data-cell');
            let newValue = target.textContent; 

            // LÓGICA: Actualizar el estado con el nuevo valor del DOM
            updateCellValue(cellCoord, newValue);
        }
    }, true); // Usamos la fase de captura para interceptar eventos antes que se propaguen


    // 3. Conectar los botones de control (Color, Limpiar, Eliminar)
    const controlsPanel = document.getElementById('column-controls');
    if (!controlsPanel) return;

    document.getElementById('btn-color').addEventListener('click', () => {
        const colorPicker = document.getElementById('color-picker');
        const selectedColor = colorPicker.value;
        // Si no hay columna seleccionada, alertar o simplemente hacer nada.
        if (estado.selectedColumn) {
            setColumnBackgroundColor(estado.selectedColumn, selectedColor);
        } else {
            alert("Por favor, selecciona una columna primero.");
        }
    });

    document.getElementById('btn-clear').addEventListener('click', () => {
        if (estado.selectedColumn) {
            if (confirm(`¿Estás seguro de que quieres borrar TODO el contenido de la columna ${estado.selectedColumn}?`)) {
                clearColumnContent(estado.selectedColumn);
            }
        } else {
            alert("Por favor, selecciona una columna primero.");
        }
    });

    document.getElementById('btn-delete').addEventListener('click', () => {
        if (estado.selectedColumn) {
            if (confirm(`¡ADVERTENCIA! ¿Estás seguro de que quieres ELIMINAR permanentemente la columna ${estado.selectedColumn}? Se borrarán los datos y el encabezado.`)) {
                deleteColumn(estado.selectedColumn);
            }
        } else {
            alert("Por favor, selecciona una columna primero.");
        }
    });
}
