function selectRow(rowId) {
    // 1. Deseleccionar cualquier fila previamente seleccionada y limpiar estilos
    const previousHeader = document.querySelector('.row-header.selected');
    if (previousHeader) {
        previousHeader.classList.remove('selected');
        const previousRowDataCells = previousHeader.closest('tr').querySelectorAll('td[contenteditable="true"]');
        previousRowDataCells.forEach(cell => cell.style.backgroundColor = '');
    }

    // 2. Obtener el header de la fila actual y marcarlo como seleccionado
    const rowHeader = document.querySelector(`.row-header[data-row="${rowId}"]`);
    if (!rowHeader) return;

    rowHeader.classList.add('selected');

    // 3. Seleccionar todas las celdas de datos asociadas a esta fila y aplicar el estilo
    const rowCells = document.querySelectorAll(`tr[data-row="${rowId}"] td[contenteditable="true"]`);
    rowCells.forEach(cell => {
        cell.classList.add('selected-cell');
        // Limpiar colores de fondo anteriores si existen, y aplicar el estilo base de selección
        cell.style.backgroundColor = ''; 
    });

    estado._selectedRowId = rowId; // Guardar el ID del estado globalmente para las acciones
}
