    // 1. Actualizar el estado (LÓGICA)
    const columns = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
    let cellsClearedCount = 0;
    for (let i = 0; i < columns.length; i++) {
        const col = columns[i];
        const cellCoord = `${col}${rowId}`;
        updateCellValue(cellCoord, ""); // Establece el valor a vacío en el estado
        cellsClearedCount++;
    }

    // 2. Actualizar la vista (DIBUJO)
    // Dado que updateCellValue ya lo hizo y render() se llama después, solo forzamos un redibujo de las celdas afectadas si es necesario.
    // Sin embargo, como estamos en el flujo de control, confiaremos en el llamado a render() final.

    guardar();
    render();
}
