function deleteSelectedRow() {
    const rowId = estado._selectedRowId;
    if (!rowId) {
        alert("Por favor, selecciona una fila para borrar.");
        return;
    }

    // 1. Remover la fila del DOM (UI)
    const rowElement = document.querySelector(`.row-header[data-row="${rowId}"]`).closest('tr');
    if (rowElement) {
        rowElement.remove();
    }

    // 2. Limpiar el estado para todas las coordenadas de esta fila (LÓGICA)
    const columns = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
    for (let i = 0; i < columns.length; i++) {
        const col = columns[i];
        const cellCoord = `${col}${rowId}`;
        delete estado[cellCoord];
    }

    // 3. Limpiar selección y guardar/redibujar
    estado._selectedRowId = null;
    guardar();
    render(); // Redibuja para asegurar que todo esté limpio
}
