### FUNCION: rebuildGridStructure
```js
/**
 * Reconstruye la estructura de las filas y encabezados después de una eliminación, 
 * re-indexando correctamente los números de fila.
 */
function rebuildGridStructure() {
    const tbody = document.querySelector('#spreadsheet-grid tbody');
    if (!tbody) return;

    // Limpiamos el contenido actual del cuerpo (todas las filas de datos)
    tbody.innerHTML = '';

    let currentRowIndex = 1; // Empezamos en la fila 1

    for (let i = 1; i <= 20; i++) {
        const rowHeaderElement = document.querySelector(`.row-header[data-row="${i}"]`);
        if (!rowHeaderElement) continue;

        // Si el elemento existe, lo reusamos y ajustamos su índice visual.
        let tr = rowHeaderElement.closest('tr');

        if (tr && !tr.classList.contains('deleted')) {
            // 1. Actualizar el contenido del encabezado de fila
            rowHeaderElement.textContent = currentRowIndex;
            rowHeaderElement.setAttribute('data-row', currentRowIndex);

            // 2. Crear una nueva fila <tr> para contener todos los datos asociados
            let newRow = document.createElement('tr');

            // Mover el encabezado de fila al inicio del tr
            newRow.appendChild(rowHeaderElement);

            // Obtener las celdas de datos (td) asociadas a esta fila original
            const dataCells = rowHeaderElement.parentElement.querySelectorAll('td');
            dataCells.forEach(cell => {
                // Reasignar la coordenada y el atributo data-cell para que coincida con el nuevo índice
                const oldCoord = cell.getAttribute('data-cell');
                const newCoord = `${cell.getAttribute('data-col')}${currentRowIndex}`;

                if (oldCoord === newCoord) {
                    // No hacer nada, la coordenada sigue siendo válida si no hubo cambios de columna.
                } else {
                     // Actualizar el atributo para que refleje el nuevo índice de fila
                    cell.setAttribute('data-cell', newCoord); 
                }

                newRow.appendChild(cell);
            });

            tbody.appendChild(newRow);
            currentRowIndex++;
        }
    }
    // Reaplicar selectores y eventos si es necesario (aunque conectar() debería manejarlo)
}
```

