// ===== DATOS: la ÚNICA fuente de verdad. Todo lo que se ve sale de acá. =====
let estado = {};
const CLAVE = "app";

/** 
 * Genera el objeto inicial del estado con todas las coordenadas predefinidas (A1 a J20).
 */
function initializeEstado() {
    const state = {};
    // Columnas A-J (índice 0 a 9)
    const columns = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
    // Filas 1-20
    for (let r = 1; r <= 20; r++) {
        for (let c = 0; c < columns.length; c++) {
            const col = columns[c];
            const cellCoord = `${col}${r}`;
            state[cellCoord] = ""; // Inicialmente vacío
        }
    }
    // Añadimos clave de estado para la selección de fila
    state['__selected_row'] = null; 
    return state;
}

// Inicializamos el estado la primera vez que se carga el script.
estado = initializeEstado();


function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) {
            const loadedState = JSON.parse(s);
            // Fusionamos lo cargado con la estructura base para asegurar que todas las claves existan,
            estado = loadedState; 
        }
    } catch (e) { 
        console.error("Error al cargar el estado:", e);
    } 
}

function guardar() { 
    try { 
        localStorage.setItem(CLAVE, JSON.stringify(estado)); 
    } catch (e) { 
        console.error("Error al guardar el estado:", e); 
    } 
}

// ===== LÓGICA: funciones que cambian `estado` (o calculan con él). NO tocan la página: sin document. =====

/**
 * Actualiza el valor de una celda en el estado.
 * @param {string} cellCoord - Coordenada de la celda (ej: "A1", "J20").
 * @param {string} value - El nuevo contenido del texto.
 */
function updateCellValue(cellCoord, value) {
    if (estado[cellCoord] !== undefined) {
        estado[cellCoord] = String(value);
    } else {
        console.warn(`Coordenada no reconocida en el estado: ${cellCoord}`);
    }
}

/**
 * Selecciona una fila específica por su índice (1 a 20).
 * @param {number} rowIndex - El número de la fila a seleccionar.
 */
function selectRow(rowIndex) {
    const rowHeader = document.querySelector(`.row-header[data-row="${rowIndex}"]`);
    if (!rowHeader) return;

    // 1. Deseleccionar cualquier otra fila primero
    document.querySelectorAll('.selected-row').forEach(el => el.classList.remove('selected-row'));

    // 2. Seleccionar la nueva fila
    const rowElement = rowHeader.closest('tr');
    if (rowElement) {
        rowElement.classList.add('selected-row');
    }

    // 3. Actualizar el estado de selección y guardar
    estado['__selected_row'] = rowIndex;
    guardar(); 

    // Habilitar/deshabilitar controles
    const controls = {
        delete: document.getElementById('btn-delete-row'),
        color: document.getElementById('btn-color-row'),
        clear: document.getElementById('btn-clear-row')
    };

    if (controls.delete) controls.delete.disabled = false;
    if (controls.color) controls.color.disabled = false;
    if (controls.clear) controls.clear.disabled = false;
}


/**
 * Elimina la fila seleccionada del estado y del DOM, y reindexa los elementos restantes.
 */
function deleteSelectedRow() {
    const selectedRowIndex = estado['__selected_row'];
    if (selectedRowIndex === undefined) return;

    // 1. Limpiar el estado: Eliminar las claves de la fila seleccionada
    for (let c = 0; c < 10; c++) { // Columnas A-J
        const colLetter = String.fromCharCode('A'.charCodeAt(0) + c);
        const cellCoord = `${colLetter}${selectedRowIndex}`;
        delete estado[cellCoord];
    }

    // 2. Limpiar el DOM: Eliminar la fila completa (header + data cells)
    const rowElement = document.querySelector(`.row-header[data-row="${selectedRowIndex}"]`).closest('tr');
    if (rowElement) {
        rowElement.remove();
    }

    // 3. Reindexación y re-renderizado de encabezados/datos
    rebuildGridStructure();

    // 4. Limpiar el estado de selección
    delete estado['__selected_row'];
    guardar();
    render(); // Redibujamos para limpiar cualquier residuo visual o de contenido
}


/**
 * Borra el contenido de todas las celdas en la fila seleccionada.
 */
function clearSelectedRowContent() {
    const selectedRowIndex = estado['__selected_row'];
    if (selectedRowIndex === undefined) return;

    // 1. LÓGICA: Limpiar el estado para esta fila
    for (let c = 0; c < 10; c++) { // Columnas A-J
        const colLetter = String.fromCharCode('A'.charCodeAt(0) + c);
        const cellCoord = `${colLetter}${selectedRowIndex}`;
        estado[cellCoord] = "";
    }

    // 2. DIBUJO: Forzar la actualización visual de las celdas vacías
    render();
}


/**
 * Cambia el color de fondo de todas las celdas en la fila seleccionada y lo aplica al DOM.
 * @param {string} hexColor - El código hexadecimal del nuevo color (#RRGGBB).
 */
function changeBackgroundColor(hexColor) {
    const selectedRowIndex = estado['__selected_row'];
    if (selectedRowIndex === undefined || !hexColor) return;

    // 1. DIBUJO: Aplicar la clase y el estilo en línea a la fila completa.
    const rowElement = document.querySelector(`.row-header[data-row="${selectedRowIndex}"]`).closest('tr');

    if (rowElement) {
        // Limpiar clases de color previas y añadir la nueva clase
        rowElement.classList.remove('custom-bg'); 
        rowElement.style.setProperty('--custom-color', hexColor); // Usamos CSS variables para el estilo global

        // Aplicar estilos directamente a los elementos hijos para asegurar que todo cambie
        const cells = rowElement.querySelectorAll('th, td');
        cells.forEach(cell => {
            cell.style.backgroundColor = hexColor;
        });
    }
    guardar(); // Guardamos el color aplicado (aunque solo sea visual)
}

/**
 * Reconstruye la estructura de las filas y encabezados después de una eliminación, 
 * re-indexando los números de fila.
 */
function rebuildGridStructure() {
    const tbody = document.querySelector('#spreadsheet-grid tbody');
    if (!tbody) return;

    // Limpiamos el contenido actual del cuerpo (todas las filas de datos)
    let rowsToRemove = [];
    document.querySelectorAll('.row-header').forEach(el => {
        rowsToRemove.push(el);
    });

    const allRows = Array.from(tbody.children);

    // Filtramos y reordenamos los elementos para reconstrucción, manteniendo solo los que no fueron eliminados
    let remainingElements = [];
    for (let i = 0; i < allRows.length; i++) {
        const rowElement = allRows[i];
        if (!rowElement.classList.contains('deleted')) { // Usamos una clase temporal si fuera necesario, pero aquí confiamos en la estructura existente
            remainingElements.push(rowElement);
        }
    }

    // Limpiar y reconstruir el <tbody>
    tbody.innerHTML = '';
    let currentRowIndex = 1; 

    remainingElements.forEach(rowElement => {
        const rowHeaderElement = rowElement.querySelector('.row-header');
        if (rowHeaderElement) {
            // 1. Actualizar el contenido del encabezado de fila
            rowHeaderElement.textContent = currentRowIndex;
            rowHeaderElement.setAttribute('data-row', currentRowIndex);

            // Asegurarse de que la clase 'selected-row' se mantenga si es necesario
            if(rowElement.classList.contains('selected-row')) {
                 rowElement.querySelector('.row-header').classList.add('selected-row'); // Reaplicar para el nuevo índice
            }

            tbody.appendChild(rowElement);
            currentRowIndex++;
        }
    });
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const cells = document.querySelectorAll('#spreadsheet-grid td[contenteditable="true"]');

    cells.forEach(td => {
        // Obtenemos la coordenada de la celda (ej: A1) usando el atributo data-cell
        const cellCoord = td.getAttribute('data-cell');

        if (cellCoord && estado[cellCoord] !== undefined) {
            // Establecemos el contenido visible con lo que está en el estado
            td.textContent = estado[cellCoord];
        } else {
             // Caso de seguridad si la coordenada no existe o el estado falló
            td.textContent = ""; 
        }
    });
}

/**
 * Conecta los listeners y eventos iniciales del DOM.
 */
function conectar() {
    const tbody = document.querySelector('#spreadsheet-grid tbody');
    if (!tbody) return;

    // 1. Event Delegation para la edición de celdas (blur)
    tbody.addEventListener('blur', (event) => {
        const target = event.target;

        if (target && target.hasAttribute('contenteditable') && target.dataset.cell) {
            const cellCoord = target.getAttribute('data-cell');
            let newValue = target.textContent; 

            // LÓGICA: Actualizar el estado con el nuevo valor del DOM
            updateCellValue(cellCoord, newValue);
        }
    }, true); // Fase de captura

    // 2. Event Listeners para la selección de fila (clic en el número)
    const rowHeaders = document.querySelectorAll('.row-header[data-row]');
    rowHeaders.forEach(header => {
        header.addEventListener('click', () => {
            const rowIndex = parseInt(header.getAttribute('data-row'));
            selectRow(rowIndex);
        });
    });

    // 3. Event Listeners para los controles de acción (Delete, Clear, Color)
    connectControls();
}


// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { 
    cargar(); 
    conectar(); 
    render(); 
}

if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
