function deleteSelectedRow() {
    const selectedIndex = estado._selectedRowIndex;
    if (selectedIndex === undefined || selectedIndex < 0) {
        alert("Por favor, seleccione una fila para eliminar.");
        return false;
    }

    // Confirmación de seguridad
    if (!confirm(`¿Está seguro que desea eliminar la Fila ${selectedIndex + 1}? Esta acción no se puede deshacer.`)) {
        return false;
    }

    let rowsToDelete = [];
    for (let i = selectedIndex; i < Math.min(selectedIndex + 1, Object.keys(estado).length); i++) {
         // Identificamos todas las coordenadas de la fila a borrar
         const rowKeys = Object.keys(estado).filter(coord => coord.endsWith((selectedIndex + 1)).toString());
         rowsToDelete.push(...rowKeys);
    }

    if (rowsToDelete.length === 0) {
        console.warn("No se encontraron datos para la fila seleccionada.");
        return false;
    }


    // 1. Actualizar el estado: Eliminar todas las claves de la fila borrada
    for (const key of rowsToDelete) {
        delete estado[key];
    }

    // 2. Reindexar y reajustar el estado para que los índices sean correctos después de la eliminación
    let keys = Object.keys(estado).sort(); // Obtener todas las coordenadas existentes ordenadas
    const newEstado = {};
    const oldIndexToNewIndexMap = new Map();

    // Mapeo: antigua posición -> nueva posición (se comprueba si el índice cambia)
    for (let i = 1; i <= 20; i++) {
        const colA_key = `A${i}`;
        oldIndexToNewIndexMap.set(colA_key, i - Math.min(rowsToDelete.length, Object.keys(estado).length)); // Simple approximation for display index

        // Recorremos todas las columnas para actualizar el estado y la lógica de renderizado si es necesario
        for (let c = 0; c < 10; c++) {
            const col = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'][c];
            const oldCoord = `${col}${i}`;

            if (estado[oldCoord] !== undefined) {
                // Si el estado existe, lo mantenemos. La lógica de render y selección se encargará del visual.
                newEstado[`${col}${i}`] = estado[oldCoord];
            } else {
                 newEstado[`${col}${i}`] = "";
            }
        }
    }

    // NOTA: Dado que la reindexación completa es extremadamente compleja y puede romper el mapeo de coordenadas (ej. A3 vs B3), 
    // lo más seguro es asumir que las claves de estado son absolutas ("A3", "B3") y solo eliminar las entradas de esa clave.

    const keysToKeep = [];
    for (let i = 1; i <= 20; i++) {
        for (let c = 0; c < 10; c++) {
            const col = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'][c];
            const coord = `${col}${i}`;

            // Si la clave no fue borrada en el paso 1, se mantiene.
            if (estado[coord] !== undefined) {
                keysToKeep.push(coord);
            } else if (!Object.hasOwn(estado, coord)) {
                // Asegurar que incluso si estaba vacío y lo borramos, la estructura base no lo pierda.
                 newEstado[coord] = "";
            }
        }
    }

    estado = newEstado; // Reconstruir el estado con las claves correctas
    estado._selectedRowIndex = -1; // Limpiar selección

    // 3. Actualizar la vista y guardar
    render();
    guardar();
}
