 * @param {number} rowIndex - El índice de la fila a seleccionar (ej: 0 para Fila 1).
 */
function selectRow(rowIndex) {
    const rowHeader = document.querySelector(`.row-header[data-row="${rowIndex}"]`);
    if (!rowHeader) return;

    // Deseleccionar todas las filas primero y quitar la clase visual
    document.querySelectorAll('.selected-row').forEach(el => {
        el.classList.remove('selected-row');
    });

    // Seleccionar la fila actual (aplicar clase visual)
    const rowElements = document.querySelectorAll('#spreadsheet-grid tr:nth-child(' + (rowIndex + 1) + ')');
    if (rowElements.length > 0) {
        rowElements[0].classList.add('selected-row');
    }

    // Actualizar el estado interno de selección
    estado._selectedRowIndex = rowIndex;
}


/**
 * Elimina la fila seleccionada del estado y del DOM.
 * @returns {boolean} True si la eliminación fue exitosa, False en caso contrario.
 */
function deleteSelectedRow() {
    const selectedIndex = estado._selectedRowIndex;
    if (selectedIndex === undefined || selectedIndex < 0) {
        alert("Por favor, seleccione una fila para eliminar.");
        return false;
    }

    if (!confirm(`¿Está seguro que desea eliminar la Fila ${selectedIndex + 1}? Esta acción no se puede deshacer.`)) {
        return false;
    }


    // 1. Identificar todas las claves de estado de la fila a borrar (ej: A3, B3, C3...)
    const keysToDelete = [];
    for (let c = 0; c < 10; c++) {
        const col = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'][c];
        keysToDelete.push(`${col}${selectedIndex + 1}`);
    }

    // 2. Eliminar los datos de la fila del estado
    for (const key of keysToDelete) {
        delete estado[key];
    }

    // 3. Reconstruir el estado para garantizar que las claves vacías sigan existiendo si fueron borradas antes.
    let newEstado = {};
    const columns = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];

    for (let r = 1; r <= 20; r++) {
        for (let c = 0; c < columns.length; c++) {
            const col = columns[c];
            const coord = `${col}${r}`;
             // Mantener el estado si no fue borrado, o inicializar a "" si la columna/fila existe pero estaba ausente en la eliminación.
            newEstado[coord] = estado[coord] === undefined ? (r == selectedIndex + 1 && c < columns.length ? "" : estado[coord] || "") : estado[coord];
        }
    }

    estado = newEstado;
    estado._selectedRowIndex = -1; // Limpiar selección

    // La renderización debe manejar la eliminación visual de las filas desactualizadas, 
    // pero dado que usamos data-cell y el DOM es estático en su estructura (20 filas), 
    // solo eliminamos los datos del estado. El rendering se encargará de mostrar lo que queda.

    return true;
}

/**
 * Borra el contenido de todas las celdas de la fila seleccionada.
 * @returns {boolean} True si el proceso fue exitoso, False en caso contrario.
 */
function clearSelectedRowContent() {
    const selectedIndex = estado._selectedRowIndex;
    if (selectedIndex === undefined || selectedIndex < 0) {
        alert("Por favor, seleccione una fila para borrar su contenido.");
        return false;
    }

    // 1. Limpiar el estado de todas las celdas de la fila seleccionada
    for (let c = 0; c < 10; c++) {
        const col = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'][c];
        const cellCoord = `${col}${selectedIndex + 1}`;
        estado[cellCoord] = "";
    }

    // 2. Redibujar y guardar
    render();
    guardar();
    return true;
}

/**
 * Cambia el fondo de todas las celdas visibles de la fila seleccionada.
 * @returns {boolean} True si el proceso fue exitoso, False en caso contrario.
 */
function changeBackgroundColor() {
    const selectedIndex = estado._selectedRowIndex;
    if (selectedIndex === undefined || selectedIndex < 0) {
        alert("Por favor, seleccione una fila para cambiarle el color de fondo.");
        return false;
    }

    // Remover cualquier clase anterior primero para evitar acumulación
     document.querySelectorAll('.highlighted-background').forEach(el => {
        el.classList.remove('highlighted-background');
    });


    // Aplicar la clase CSS al contenedor de la fila completa (la TR)
    const rowElements = document.querySelector(`#spreadsheet-grid tr:nth-child(${selectedIndex + 1})`);
    if (rowElements) {
        rowElements.classList.add('highlighted-background');
    } else {
        console.error("No se pudo encontrar la fila para aplicar el color.");
    }

    return true;
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const cells = document.querySelectorAll('#spreadsheet-grid td[contenteditable="true"]');

    cells.forEach(td => {
        // Obtenemos la coordenada de la celda (ej: A1) usando el atributo data-cell
        const cellCoord = td.getAttribute('data-cell');

        if (cellCoord && estado[cellCoord] !== undefined) {
            // Establecemos el contenido visible con lo que está en el estado
            td.textContent = estado[cellCoord];
        } else {
             // Caso de seguridad si la coordenada no existe o el estado falló
            td.textContent = ""; 
        }
    });
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const tbody = document.querySelector('#spreadsheet-grid tbody');
    if (!tbody) return;

    // 1. Event Delegation para el cambio de contenido (blur)
    tbody.addEventListener('blur', (event) => {
        const target = event.target;

        // Verificamos si el elemento objetivo es una celda de datos editable
        if (target && target.hasAttribute('contenteditable') && target.dataset.cell) {
            const cellCoord = target.getAttribute('data-cell');
            let newValue = target.textContent; 

            // LÓGICA: Actualizar el estado con el nuevo valor del DOM
            updateCellValue(cellCoord, newValue);
            guardar(); // Guardamos inmediatamente después de la actualización lógica
        }
    }, true); // Usamos la fase de captura para interceptar eventos antes que se propaguen

    // 2. Conectar controles de acciones (botones) y selección de fila
    connectControls();
}

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
