```js
/**
 * Maneja la selección de una fila basándose en su índice.
 * @param {number|string} rowIndex - Índice de la fila (ej: "3").
 */
function handleSelectRow(rowIndex) {
    // 1. Limpiar selección anterior y deshabilitar controles
    const previousSelectedRow = document.querySelector('.selected-row');
    if (previousSelectedRow) {
        previousSelectedRow.classList.remove('selected-row');
    }

    // 2. Aplicar nueva selección
    const rowElement = document.querySelector(`.data-row[data-row-index="${rowIndex}"]`);
    if (!rowElement) {
        console.warn(`No se encontró la fila con índice: ${rowIndex}`);
        return;
    }

    // Agregar clase de selección para el estilo visual (CSS)
    rowElement.classList.add('selected-row');

    // Actualizar estado interno y controles
    estado.selectedRowIndex = rowIndex;
    document.getElementById('clear-row-btn').disabled = false;
    document.getElementById('apply-color-btn').disabled = false;

    // Opcional: Enfocar la primera celda para mejor UX
    const firstCell = rowElement.querySelector('[contenteditable="true"]');
    if (firstCell) {
        firstCell.focus();
    }
}
