### FUNCION: handleSelectRow
```js
function handleSelectRow(event) {
    const target = event.currentTarget;
    // Los row-headers tienen data-row con el número de la fila
    const rowNumber = parseInt(target.getAttribute('data-row'));

    if (isNaN(rowNumber)) return;

    // 1. Deseleccionar cualquier otra fila y resetear estilos/estado visuales
    document.querySelectorAll('.data-row').forEach(row => {
        row.classList.remove('selected');
        // Limpiar colores de fondo de todas las celdas del DOM al deseleccionar
        const cells = row.querySelectorAll('td');
        cells.forEach(cell => cell.style.backgroundColor = '');
    });

    // 2. Seleccionar la nueva fila y aplicar estilos visuales
    const selectedRowElement = target.closest('.data-row');
    if (selectedRowElement) {
        selectedRowElement.classList.add('selected');

        // Actualizar el estado de selección global (para que render() lo use si es necesario, aunque aquí usamos variables directas)
        estado._selectedRow = rowNumber;

        // 3. Actualizar la interfaz de usuario con la fila seleccionada
        document.getElementById('selected-row-number').textContent = rowNumber;
    } else {
        // Si por alguna razón no se encuentra el contenedor, limpiar todo
        estado._selectedRow = null;
        document.getElementById('selected-row-number').textContent = 'Ninguna';
    }
}
