### FUNCION: clearSelectedRow
```js
function clearSelectedRow() {
    const rowNumber = estado._selectedRow;
    if (isNaN(rowNumber) || rowNumber === null) {
        alert("Por favor, seleccione una fila primero.");
        return false;
    }

    // 1. Actualizar el estado para todas las celdas de la fila seleccionada
    let needsSave = false;
    for (let colIndex = 0; colIndex < 10; colIndex++) { // A-J son 10 columnas
        const colLetter = String.fromCharCode('A'.charCodeAt(0) + colIndex);
        const cellCoord = `${colLetter}${rowNumber}`;
        if (estado[cellCoord] !== "") {
            updateCellValue(cellCoord, "");
            needsSave = true;
        }
    }

    // 2. Actualizar el DOM visualmente
    document.querySelectorAll(`[data-row="${rowNumber}"] td`).forEach(td => {
        td.textContent = "";
        // También limpiar colores de fondo al borrar contenido
        td.style.backgroundColor = ''; 
    });

    if (needsSave) {
        guardar();
        render(); // Re-render para asegurar que el estado se refleja
    }
    return true;
}
