    }

    // 1. Eliminar el contenido del estado para todas las celdas de la fila seleccionada
    let needsSave = false;
    for (let colIndex = 0; colIndex < 10; colIndex++) { // A-J son 10 columnas
        const colLetter = String.fromCharCode('A'.charCodeAt(0) + colIndex);
        const cellCoord = `${colLetter}${rowNumber}`;
        if (estado[cellCoord] !== undefined) {
            delete estado[cellCoord];
            needsSave = true;
        }
    }

    // 2. Eliminar la fila del DOM visualmente
    const rowElement = document.querySelector(`tr[data-row="${rowNumber}"]`);
    if (rowElement) {
        rowElement.remove();
    }

    // 3. Actualizar estado y UI
    estado._selectedRow = null;
    document.getElementById('selected-row-number').textContent = 'Ninguna';
    guardar();
    render();
    return true;
}
