```js
/**
 * Selecciona visual y funcionalmente una fila específica por su número.
 * @param {number} rowNum - El número de la fila a seleccionar (ej: 3).
 */
function selectRowByNumber(rowNum) {
    // Deseleccionar cualquier fila previamente seleccionada
    document.querySelectorAll('.selected-row').forEach(el => el.classList.remove('selected-row'));

    const rowElement = document.querySelector(`.row-header[data-row="${rowNum}"]`).closest('tr');
    if (rowElement) {
        // 1. Selección Visual y Estado Global
        rowElement.classList.add('selected-row');
        window.selectedRowElement = rowElement;

        // 2. Actualizar Controles de la UI
        updateControlState(rowElement);
    } else {
        console.warn(`Fila ${rowNum} no encontrada.`);
        window.selectedRowElement = null;
        updateControlState(null);
    }
}
