        // Determinar el fondo inicial para el selector de color (tomar del primer TD, si existe)
        const firstCell = rowElement.querySelector('td');
        if (firstCell) {
            colorPicker.value = firstCell.style.backgroundColor || '#ffffff';
        } else {
             // Si no hay celdas de datos visibles, usar blanco por defecto
            colorPicker.value = '#ffffff'; 
        }

    } else {
        btnClear.disabled = true;
        btnColor.disabled = true;
        btnDelete.disabled = true;
        colorPicker.value = '#ffffff'; // Resetear color picker
    }
}
