### FUNCION: toggleVisibility
```js
/**
 * Alterna la visibilidad de una columna o fila específica en el DOM.
 * @param {string} type - 'column' o 'row'.
 * @param {string} identifier - El identificador (ej: "A" para columnas, "1" para filas).
 */
function toggleVisibility(type, identifier) {
    let isHidden = false;

    if (type === 'column') {
        // 1. Buscar y ocultar el encabezado de columna
        const colHeader = document.querySelector(`.col-header[data-column="${identifier}"]`);
        if (colHeader) {
            colHeader.classList.toggle('hidden');
            isHidden = !colHeader.classList.contains('hidden');

            // 2. Ocultar todas las celdas de datos asociadas a esta columna
            const cellsToHide = document.querySelectorAll(`[data-cell^="${identifier}"]`);
            cellsToHide.forEach(cell => {
                cell.classList.toggle('hidden', !isHidden);
            });
        }

    } else if (type === 'row') {
        // 1. Buscar y ocultar el encabezado de fila
        const rowHeader = document.querySelector(`.row-header[data-row="${identifier}"]`);
        if (rowHeader) {
            rowHeader.classList.toggle('hidden');
            isHidden = !rowHeader.classList.contains('hidden');

            // 2. Ocultar todas las celdas de datos asociadas a esta fila
            const cellsToHide = document.querySelectorAll(`[data-cell*="${identifier}"]`);
            cellsToHide.forEach(cell => {
                cell.classList.toggle('hidden', !isHidden);
            });
        }
    }

    // Opcional: Actualizar el estado si esto fuera un requisito de persistencia, 
    // pero por ahora solo manipulamos la vista.
}
