function initializeEstado() {
    const state = {};
    // Columnas A-J (índice 0 a 9)
    const columns = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
    // Filas 1-20
    for (let r = 1; r <= 20; r++) {
        for (let c = 0; c < columns.length; c++) {
            const col = columns[c];
            const cellCoord = `${col}${r}`;
            state[cellCoord] = ""; // Inicialmente vacío
        }
    }
    // Estado de visibilidad inicial
    state.hiddenColumns = []; 
    state.hiddenRows = [];
    return state;
}
