### FUNCION: conectar
```js
function conectar() {
    const tbody = document.querySelector('#spreadsheet-grid tbody');
    if (!tbody) return;

    // --- Eventos de Edición (blur) ---
    tbody.addEventListener('blur', (event) => {
        const target = event.target;

        // Verificamos si el elemento objetivo es una celda de datos editable
        if (target && target.hasAttribute('contenteditable') && target.dataset.cell) {
            const cellCoord = target.getAttribute('data-cell');
            let newValue = target.textContent; 

            // 1. LÓGICA: Actualizar el estado con el nuevo valor del DOM
            updateCellValue(cellCoord, newValue);
        }
    }, true); // Usamos la fase de captura para interceptar eventos antes que se propaguen


    // --- Eventos de Columna/Fila (Clic en Headers) ---

    // 1. Manejar clic en encabezados de columna (A-J)
    const columnHeaders = document.querySelectorAll('.col-header');
    columnHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const letter = this.getAttribute('data-column');
            toggleHideColumn(letter);
        });
    });

    // 2. Manejar clic en encabezados de fila (1-20)
    const rowHeaders = document.querySelectorAll('.row-header');
    rowHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const number = this.getAttribute('data-row');
            toggleHideRow(number);
        });
    });

    // 3. Inicializar controles de Ocultar/Mostrar (Delegación)
    document.getElementById('col-selector').addEventListener('change', updateSelectors);
    document.getElementById('row-selector').addEventListener('change', updateSelectors);

    document.getElementById('toggle-column').addEventListener('click', () => {
        const colSelector = document.getElementById('col-selector');
        if (colSelector.value) {
            const letter = colSelector.value;
            // Aquí se podría añadir lógica de confirmación, pero por ahora solo togglea
            toggleHideColumn(letter); 
        }
    });

    document.getElementById('toggle-row').addEventListener('click', () => {
        const rowSelector = document.getElementById('row-selector');
        if (rowSelector.value) {
            const number = rowSelector.value;
            // Aquí se podría añadir lógica de confirmación, pero por ahora solo togglea
            toggleHideRow(number); 
        }
    });
}

/**
 * Rellena los selectores de columna y fila con todas las opciones disponibles.
 */
function updateSelectors() {
    const columns = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
    const rows = Array.from({ length: 20 }, (_, i) => i + 1);

    // Llenar selectores de columnas
    const colSelector = document.getElementById('col-selector');
    colSelector.innerHTML = '<option value="" disabled selected>Seleccionar Columna</option>';
    columns.forEach(col => {
        const option = document.createElement('option');
        option.value = col;
        option.textContent = `Columna ${col}`;
        colSelector.appendChild(option);
    });

    // Llenar selectores de filas
    const rowSelector = document.getElementById('row-selector');
    rowSelector.innerHTML = '<option value="" disabled selected>Seleccionar Fila</option>';
    rows.forEach(row => {
        const option = document.createElement('option');
        option.value = String(row);
        option.textContent = `Fila ${row}`;
        rowSelector.appendChild(option);
    });
}
