### FUNCION: render
```js
function render() {
    // 1. Ocultar/Mostrar Headers y Contenedores de Columnas/Filas
    const hiddenCols = estado.hiddenColumns;
    const hiddenRows = estado.hiddenRows;

    // A. Manipular las celdas del encabezado de columna (A-J)
    document.querySelectorAll('.col-header').forEach(th => {
        const colLetter = th.getAttribute('data-column');
        if (hiddenCols.includes(colLetter)) {
            th.classList.add('hidden-col');
        } else {
            th.classList.remove('hidden-col');
        }
    });

    // B. Manipular las filas completas en el body
    const rows = document.querySelectorAll('#spreadsheet-grid tbody tr');
    rows.forEach(row => {
        const rowNumberMatch = row.querySelector('.row-header').getAttribute('data-row');
        if (rowNumberMatch && hiddenRows.includes(rowNumberMatch)) {
            row.classList.add('hidden-row');
        } else {
            row.classList.remove('hidden-row');
        }
    });


    // 2. Renderizar contenido de celdas individuales
    const cells = document.querySelectorAll('#spreadsheet-grid td[contenteditable="true"]');

    cells.forEach(td => {
        const cellCoord = td.getAttribute('data-cell');
        const [colLetter, rowNumber] = cellCoord.match(/([A-Z]+)([0-9]+)/);

        // Determinar si la celda debe estar oculta por su columna o fila
        let isHiddenByCol = hiddenCols.includes(colLetter);
        let isHiddenByRow = hiddenRows.includes(rowNumber);

        td.style.display = (isHiddenByCol || isHiddenByRow) ? 'none' : '';

        // Establecer el contenido visible con lo que está en el estado, solo si no está oculto
        if (!isHiddenByCol && !isHiddenByRow) {
            if (cellCoord && estado[cellCoord] !== undefined) {
                td.textContent = estado[cellCoord];
            } else {
                 td.textContent = ""; 
            }
        } else {
             // Si está oculto, vaciamos el contenido para asegurar que no muestre nada (aunque style:display debería manejarlo)
            td.textContent = "";
        }
    });
}
```

### FUNCION: toggleHideColumn
```js
function toggleHideColumn(columnIndex) {
    const col = columnIndex;
    // 1. Obtener el encabezado de la columna y alternar su visibilidad
    const colHeader = document.querySelector(`.col-header[data-col-index="${col}"]`);
    if (!colHeader) return;

    let isHidden = colHeader.style.display === 'none';

    // Alternar la visibilidad del encabezado de columna (la letra A, B...)
    colHeader.style.display = isHidden ? '' : 'none';

    // 2. Encontrar todas las celdas de datos correspondientes en el cuerpo de la tabla
    // Las columnas de datos están en índices 1 a 10 (A a J).
    // nth-child(N) donde N=col+2 porque se cuenta la columna del row_header (índice 0)
    const cellsToToggle = document.querySelectorAll('#spreadsheet-grid tbody td:nth-child(' + (col + 2) + ')');

    if (isHidden) {
        // Si estaba oculto, lo mostramos
        cellsToToggle.forEach(cell => {
            cell.style.display = '';
        });
    } else {
        // Si estaba visible, lo ocultamos
        cellsToToggle.forEach(cell => {
            cell.style.display = 'none';
        });
    }
}
```

### FUNCION: toggleHideRow
```js
function toggleHideRow(rowIndex) {
    const rowElement = document.querySelector(`#spreadsheet-grid tbody tr:nth-child(${rowIndex})`);
    if (!rowElement) return;

    // Toggle visibility of the entire row and its header cell (the number)
    let isHidden = rowElement.style.display === 'none';

    // Alternar la visibilidad de la fila completa y su encabezado numérico
    rowElement.style.display = isHidden ? '' : 'none';
    document.querySelector('.row-header:nth-child(' + rowIndex + ')').style.display = isHidden ? '' : 'none';
}
